import{salary087}from'./open-explorer-087.js';
import{scoreOnetInterest,onetQuestions,validOnetAnswer}from'./onet-assessment.js';
import{completeSalaryProgression084 as salaryProgression}from'./complete-salaries-084.js';
import{lifestyleIncomeRange}from'./lifestyle-story.js';
import{educationRoutesFor}from'./education-routes.js';
import{explorerResults,discoveryTopics056}from'./open-explorer-087.js';
import{explorerBudget}from'./explorer-053-budget.js';
import{careerFamilies}from'./guide-state.js';
export function boardOffer(o,{rank=0,top=false,candidate=false,fields=[],routes=o.routes||educationRoutesFor(o),amount=null,evidence=[],r=null,mixed=false,confirmation=null}={}){const p=salary087(o.id)||salaryProgression(o.id),entry=p?.stages.find(s=>s.key==='entry');return{id:o.id,title:o.title,rank,top,candidate,mixedInterests:mixed,payPlanningOnly:!!p?.planningOnly,fields,routes,entry:entry?.amount??amount,year5:p?.stages.find(s=>s.key==='year5')?.amount??null,requiresExperience:!!o.requiresExperience||!!p?.entryContext,variableHours:!!p?.variableHours,preparation:o.preparation?.typicalEducation||[o.finance?.requirements?.typicalEntry||'Check exact requirements'],training:p?.paidTraining?{label:p.paidTraining.label||'Paid preparation',amount:p.paidTraining.amount}:null,paySources:p?.sources||[],payNotes:p?.notes||['Five-year pay is not estimated.'],entryBasis:p?.label||'Current occupation wage reference',geography:p?.geography||'See career source',period:p?.referencePeriod||'Current wage reference',routeGroup:routes.some(r=>r.key==='graduate')?'graduate':routes.some(r=>r.key==='college')?'college':routes.some(r=>r.key==='program')?'program':routes.some(r=>r.key==='apprenticeship')?'apprenticeship':'work',knownEvidence:evidence,confirmation,correlation:r,broadDisagreement:r!==null&&r<0};}
export function liveBoardData(s){const interest=scoreOnetInterest(s),result=explorerResults(s),supported=result.rows.filter(r=>r.specific.supported),candidates=result.rows.filter(r=>!r.specific.supported&&(r.r>=.608||r.specific.evidence.length>0||r.activityTopics?.length>0)),goal=lifestyleIncomeRange(s.finance.lifestyle);const pack=(r,i,candidate)=>boardOffer(r.o,{rank:i,top:!candidate&&i<3,candidate,fields:r.fields,amount:explorerBudget(s,r.o).amount,evidence:[...r.specific.evidence.map(e=>e.text),...(r.activityTopics||[]).map(id=>'Activity you selected: '+(discoveryTopics056.find(t=>t.id===id)?.title||onetQuestions.find(q=>q.id===id)?.text||id))].slice(0,3),r:r.r,mixed:r.specific.contrary.length>0,confirmation:{requirement:r.specific.requirement,asked:r.specific.asked,taskContexts:r.specific.taskDomains.length,specificInterests:r.specific.specificDomains.length,missing:r.specific.missing.map(q=>q.prompt),contrary:r.specific.contrary.map(q=>q.prompt)}});return{fields:careerFamilies.map(f=>({id:f.id,title:f.title})),profiles:[{id:'own-plan',name:s.profile?.nickname||'Your plan',firstName:s.profile?.nickname||'you',profileAnswered:interest.answered,profileComplete:interest.complete,resumeInterestIndex:Math.max(0,onetQuestions.findIndex(q=>!validOnetAnswer(s.profileJourney?.officialInterest?.answers?.[q.id]))),lifestyle:{target:goal.minimum,comfortable:goal.breathingRoom,monthlySpending:goal.spending},supported:supported.map((r,i)=>pack(r,i,false)),candidates:candidates.map((r,i)=>pack(r,i,true)),candidateCount:candidates.length}],saved:s.careerLibrary?.saved||[]};}
